import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office Kata", () => {
  describe("quote - base premiums", () => {
    it.todo("empty item list yields premium 5 G (only processing fee)");
    it.todo("a single sword yields premium 105 G (100 base + 5 fee)");
    it.todo("a single amulet yields premium 65 G (60 base + 5 fee)");
    it.todo("a single staff yields premium 85 G (80 base + 5 fee)");
    it.todo("a single potion yields premium 45 G (40 base + 5 fee)");
    it.todo("a single rune yields premium 30 G (25 base + 5 fee)");
    it.todo("a single moonstone yields premium 30 G (25 base + 5 fee)");
  });

  describe("quote - components and blocks", () => {
    it.todo("2 runes yield base premium 50 G (+5 fee = 55 G)");
    it.todo("3 runes yield base premium 60 G block (+5 fee = 65 G)");
    it.todo("4 runes yield base premium 100 G, no block (+5 fee = 105 G)");
    it.todo("7 runes yield base premium 175 G (+5 fee = 180 G)");
    it.todo("2 runes + 1 moonstone yield base premium 75 G, no block (+5 fee = 80 G)");
    it.todo("3 runes + 3 moonstones yield base premium 120 G, two blocks (+5 fee = 125 G)");
  });

  describe("quote - modifiers", () => {
    it.todo("a cursed sword adds 50% risk surcharge: 100+50 base → 155 G (150 + 5 fee)");
    it.todo("a high-enchantment sword (enchantment 5) adds 30%: 100+30 base → 135 G (130 + 5 fee)");
    it.todo("sword with enchantment 4 gets no high-enchantment surcharge: 105 G (100 + 5 fee)");
    it.todo("cursed + enchantment 9 sword applies both surcharges: 100+50+30 → 185 G (180 + 5 fee)");
    it.todo("cursed surcharge applies to the cursed item's base premium, not policy total (cursed sword + plain amulet → 210 G before fee)");
    it.todo("customer with exactly 2 years gets 20% loyalty discount: sword → 85 G (80 + 5 fee)");
    it.todo("first insurance (0 years, no prior) adds 10% initial assessment surcharge");
    it.todo("follow-up contract (second quote) gets 15% discount");
  });

  describe("quote - integration examples", () => {
    it.todo("newcomer with cursed sword (0y, first contract) → premium 165 G");
    it.todo("long-standing customer's second contract, cursed enchantment-7 sword → premium 160 G");
    it.todo("item-specific modifiers apply to item base; policy-wide modifiers apply to total; fee last");
  });

  describe("quote - rounding in MHPCO's favor", () => {
    it.todo("premium calculating to 197.5 G is rounded up to 198 G");
    it.todo("intermediate amounts kept as fractions, only final premium rounded");
  });

  describe("quote - policy-wide modifiers", () => {
    it.todo("policy base premium is sum of all item base premiums");
  });

  describe("quote - errors", () => {
    it.todo("unknown item type (broomstick) causes CLI to exit non-zero and write error to stderr, no results");
  });

  describe("claim - standard reimbursement", () => {
    it.todo("regular steel sword enchantment 3, damage 500 → payout 400 (500 - deductible 100)");
    it.todo("rune damage 200 → payout 100 (200 - deductible 100, no special clause)");
    it.todo("dragon-material sword enchantment 5, damage 800 → payout 700 (full - 100 deductible)");
    it.todo("steel sword enchantment 9, damage 1000 → payout 400 (50% then -100 deductible: 500-100)");
    it.todo("dragon-material sword enchantment 8, damage 1000 → payout 400 (50% rule wins, then deductible)");
    it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 (50% rule wins, then deductible)");
    it.todo("enchanted sword (enchantment 8) with damage less than deductible → payout 0");
  });

  describe("claim - multiple items and deductible", () => {
    it.todo("dragon attack damaging sword 500 and amulet 300 → payout 600 (deductible 100 per item)");
  });

  describe("claim - insurance sum and cap", () => {
    it.todo("policy covering two swords has insurance sum 2000, cap 4000");
    it.todo("policy covering a sword and an amulet has insurance sum 1600, cap 3200");
    it.todo("cursed sword (iv 1000) has cap 2000 - modifiers do not raise cap");
    it.todo("policy covering sword + 3 rune block: insurance sum 1750, block discount affects premium only");
  });

  describe("claim - multiple damages of same type", () => {
    it.todo("two sword damage entries are each separate damage with own deductible");
    it.todo("more damage entries of a type than covered → CLI exits non-zero, claim rejected");
  });

  describe("claim - cap exhaustion", () => {
    it.todo("sword insured (cap 2000); first claim 1500 → payout 1400, remaining cap 600");
    it.todo("second claim 1500 → payout 600, remaining cap 0 (reduced to remaining cap)");
  });

  describe("claim - errors", () => {
    it.todo("claim references item not in policy → CLI exits non-zero, error to stderr");
    it.todo("claim with unknown item type → CLI exits non-zero, error to stderr");
    it.todo("claim with damage amount -200 → CLI exits non-zero, error to stderr");
  });

  describe("rounding - payouts", () => {
    it.todo("payout calculating to 350.5 G is rounded down to 350 G");
  });

  describe("CLI integration", () => {
    it.todo("reads JSON from stdin and writes results JSON to stdout for a quote");
    it.todo("reads JSON from stdin and writes results JSON to stdout for a claim (payout + remainingCap)");
  });
});

