export function runScenario(scenario: Scenario): { results: unknown[] } {
  const results = scenario.steps.map((step) => {
    if (step.op === "quote") {
      return { premium: computeBasePremium(step.items) + 5 };
    }
    return { premium: 5 };
  });
  return { results };
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

function computeBasePremium(items: Item[]): number {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  let total = 0;
  for (const [type, count] of counts) {
    if (COMPONENT_TYPES.has(type) && count === 3) {
      total += 60;
    } else {
      total += (BASE_PREMIUMS[type] ?? 0) * count;
    }
  }
  return total;
}

